    implicit_hypothesis: z3.BoolRef = xy_nonzero
    result: dict[str, z3.BoolRef] = {}

    fs: IntVar = es - (nlbs + one)
    fe: IntVar = ee - (nlbe + one)
    gx: IntVar = ex - (p - (ntbx + one))
    gy: IntVar = ey - (p - (ntby + one))
    gs: IntVar = es - (p - (ntbs + one))
    ge: IntVar = ee - (p - (ntbe + one))

    x_one0: z3.BoolRef = z3.And(~x_zero, lbx, tbx, nlbx + ntbx == p - two)
    y_one0: z3.BoolRef = z3.And(~y_zero, lby, tby, nlby + ntby == p - two)
    x_one1: z3.BoolRef = z3.And(~x_zero, ~lbx, ~tbx, nlbx + ntbx == p - two)
