    y_g00: z3.BoolRef = z3.And(~y_zero, ~lby, ~tby, nlby + ntby < p - three)
    x_g01: z3.BoolRef = z3.And(~x_zero, ~lbx, tbx, nlbx + ntbx < p - three)
